INSERT INTO questions (source, year, subject, topic, enunciado, opcoes, gabarito, explicacao) VALUES
  ('exam', 2024, 'Português', 'Interpretação de texto', 'Item 1 (TPS 2024): (...) as nações latinas do Novo Mundo não se podem queixar de deslembradas. Cada incidente, ainda sem grande relevo, encontra repercussão na imprensa europeia. Não aparecem, é verdade, nenhuns desses longos estudos, circunstanciados e sábios, onde os mestres em assuntos internacionais dizem o que sabem sobre a história política, social e econômica do país de que se ocupam, para daí deduzirem os se | No terceiro período do texto, o termo “circunstanciados” se refere às condicionantes da produção do conhecimento científico da época, ou às circunstâncias da epistemologia vigente. 2 Na construção argumentativa do texto, o autor faz uma pausa retórica mediante o emprego do “Não” (quarto período), para relativizar sua oposição ao conteúdo do período imediatamente anterior, e repete, nos dois últimos períodos, a expressão “se limitam” com o propósito de reforçar sua crítica à visão eurocêntrica, por ele considerada superficial e pretensamente superior. 3 Infere-se do texto ', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2024, 'Português', 'Interpretação de texto', 'Item 2 (TPS 2024): Afinal, os homens nascem iguais, apenas sem uma definição completa da natureza. Em Rousseau, por exemplo, com a noção do “bom selvagem”, essa ideia estará absolutamente presente. A alteridade desses “novos homens” transformada em modelo lógico se contrapunha à experiência ocidental. Como concluía Rousseau sobre a origem da desigualdade entre os homens, “se há uma bondade original da natureza human | No dia 9 de agosto de 2023, ainda em Belém, os presidentes dos Estados-partes no TCA mantiveram encontro com mandatários e representantes de países em desenvolvimento de outras regiões do mundo com florestas tropicais, como Indonésia, República Democrática do Congo e República do Congo, tendo sido adotado, na ocasião, o documento Unidos por Nossas Florestas — Comunicado Conjunto dos Países Florestais em Desenvolvimento em Belém, em que conclamam os países desenvolvidos a cumprirem suas obrigações de financiamento climático.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2024, 'Português', 'Interpretação de texto', 'Item 3 (TPS 2024): Afinal, os homens nascem iguais, apenas sem uma definição completa da natureza. Em Rousseau, por exemplo, com a noção do “bom selvagem”, essa ideia estará absolutamente presente. A alteridade desses “novos homens” transformada em modelo lógico se contrapunha à experiência ocidental. Como concluía Rousseau sobre a origem da desigualdade entre os homens, “se há uma bondade original da natureza human | Realizada em Belém do Pará, a reunião contou com a participação de todos os países signatários do TCA, além de representantes de países convidados e de organismos internacionais, tendo sido a primeira reunião de presidentes dos Estados-partes no TCA desde 2009.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2024, 'Português', 'Interpretação de texto', 'Item 4 (TPS 2024): Afinal, os homens nascem iguais, apenas sem uma definição completa da natureza. Em Rousseau, por exemplo, com a noção do “bom selvagem”, essa ideia estará absolutamente presente. A alteridade desses “novos homens” transformada em modelo lógico se contrapunha à experiência ocidental. Como concluía Rousseau sobre a origem da desigualdade entre os homens, “se há uma bondade original da natureza human | Na declaração presidencial emitida por ocasião da reunião, os mandatários dos Estados-partes no TCA concordaram em promover mecanismos inovadores de financiamento para ações climáticas, incluindo a troca de dívidas por ações climáticas. Questão 12 As relações entre Brasil e Argentina são marcadas pela intensidade dos fluxos bilaterais de comércio e de investimentos e pela integração da infraestrutura física dos países. Além disso, o perfil do comércio bilateral entre Brasil e Argentina é caracterizado pela grande participação da indústria de transformação e pelo elevado v', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
